package com.example.etl.ingestion.handlers

import com.example.etl.config.JobConfig
import com.example.etl.sql.{SqlParserService, LogicalPlanValidator}
import com.example.etl.logic.Scd2LogicUtil
import com.example.etl.reconciliation.ReconciliationService
import com.example.etl.dq.{DataQualityService, DataQualityReport}
import com.example.etl.util.LoggingUtil // Import LoggingUtil
import org.apache.spark.sql.{DataFrame, SparkSession, SaveMode, Dataset}
import org.apache.spark.sql.functions._
import org.apache.spark.sql.types._
import org.apache.log4j.Logger
import java.sql.Timestamp
import java.time.Instant
import scala.util.parsing.json.JSON

object Scd2LogicHandler {
  @transient lazy val logger: Logger = Logger.getLogger(getClass.getName)
  def execute(jobConfig: JobConfig, spark: SparkSession): (Option[Long], Option[Long], Option[DataQualityReport]) = {
    logger.info(s"Executing SCD2 for job_name: ${jobConfig.job_name}")
    val pTs=Timestamp.from(Instant.now()); val hTs=Timestamp.valueOf("9999-12-31 23:59:59")
    var iSrcCnt:Option[Long]=None; var tSrcCnt:Option[Long]=None; var tCurCnt:Option[Long]=None; var rWriteCnt:Option[Long]=None; var dqRepOpt:Option[DataQualityReport]=None
    val scdC=Scd2LogicUtil.ScdColumnNames(skIdCol=jobConfig.scd2_surrogate_key_column.getOrElse("sk_id"),validFromCol=jobConfig.scd2_valid_from_column.getOrElse("valid_from_ts"),validToCol=jobConfig.scd2_valid_to_column.getOrElse("valid_to_ts"),versionCol=jobConfig.scd2_version_column.getOrElse("version"),isCurrentCol=jobConfig.scd2_current_flag_column.getOrElse("is_current"),changeTypeCol="change_type")
    if(jobConfig.source_connection_details.isEmpty)throw new IllegalArgumentException(s"Src conn details req for ${jobConfig.job_name}")
    var rawDF:DataFrame=null; jobConfig.source_type.toUpperCase match {case "FILE"=>val p=jobConfig.source_connection_details.get;val f=jobConfig.source_format.getOrElse(throw new IllegalArgumentException("src_fmt req")).toLowerCase;val r=spark.read.format(f);jobConfig.source_format_options.foreach(o=>JSON.parseFull(o)match{case Some(m:Map[String,String])=>r.options(m)case _=>});jobConfig.source_schema.foreach(s=>r.schema(s));rawDF=r.load(p) case "HIVE_TABLE"=>val t=jobConfig.source_connection_details.get;try rawDF=spark.table(t)catch{case e:Exception=>throw new RuntimeException(s"Fail read HIVE $t:${e.getMessage}",e)} case o=>throw new UnsupportedOperationException(s"Src type '$o' not supported SCD2.")}\n    if(jobConfig.audit_level.toUpperCase!="NONE")try iSrcCnt=Some(rawDF.count())catch{case e:Exception=>logger.warn(s"No cnt raw_src ${jobConfig.job_name}:${e.getMessage}",e)}\n    logger.info(s"Raw src read ${jobConfig.job_name}. Recs:${iSrcCnt.getOrElse("N/A")}");if(logger.isDebugEnabled){logger.debug(s"Schema rawDF ${jobConfig.job_name}:");rawDF.printSchema();logger.debug(s"Sample rawDF ${jobConfig.job_name} (masked):");val rShow=jobConfig.log_masking_columns.filter(_.trim.nonEmpty).map(c=>LoggingUtil.maskDataFrame(rawDF,c.split(',').map(_.trim))).getOrElse(rawDF);rShow.show(5,false)}\n    val tfmDF:DataFrame=jobConfig.sql_logic match {case Some(s)if s.trim.nonEmpty=>{logger.info(s"SQL SCD src tfm ${jobConfig.job_name}:${s.take(100)}");val v=jobConfig.job_name+"_raw_scd_src";rawDF.createOrReplaceTempView(v);var pS=s;val prf="spark.etl.param.";spark.conf.getAll.foreach{case(k,vl)=>if(k.startsWith(prf)){val pN=k.substring(prf.length);pS=pS.replace(s"$${$pN}",vl)}};val pL=SqlParserService.parse(pS,spark).getOrElse(throw new RuntimeException("SQL parse fail"));LogicalPlanValidator.validate(pL) match { case Right(_) => /* Do nothing */ case Left(errs) => throw new RuntimeException(s"Plan invalid for ${jobConfig.job_name}: ${errs.mkString(";")}") };try Dataset.ofRows(spark,pL)catch{case e:Exception=>throw new RuntimeException(s"Err exec SCD SQL ${jobConfig.job_name}:${e.getMessage}",e)}}case _=>logger.info(s"No sql_logic, use raw_src ${jobConfig.job_name}.");rawDF}\n    if(jobConfig.audit_level.toUpperCase!="NONE")try tSrcCnt=Some(tfmDF.count())catch{case e:Exception=>logger.warn(s"No cnt tfm_src ${jobConfig.job_name}:${e.getMessage}",e)}\n    logger.info(s"Tfm src SCD2 ${jobConfig.job_name}. Recs:${tSrcCnt.getOrElse("N/A")}");if(logger.isDebugEnabled){logger.debug(s"Schema tfmDF ${jobConfig.job_name}:");tfmDF.printSchema();logger.debug(s"Sample tfmDF ${jobConfig.job_name} (masked):");val tShow=jobConfig.log_masking_columns.filter(_.trim.nonEmpty).map(c=>LoggingUtil.maskDataFrame(tfmDF,c.split(',').map(_.trim))).getOrElse(tfmDF);tShow.show(5,false)}\n    val tgtId=jobConfig.target_table_or_path\n    val tgtCurDF:DataFrame=try{val tF=jobConfig.target_type.toUpperCase match{case "FILE"|"HDFS"=>spark.read.format(jobConfig.target_format.getOrElse("parquet")).load(tgtId) case "HIVE_TABLE"=>spark.table(tgtId) case o=>throw new UnsupportedOperationException(s"Tgt type '$o' not supported SCD2 read.")};tF.filter(col(scdC.isCurrentCol)===true)}catch{case e:org.apache.spark.sql.AnalysisException if e.getMessage.toLowerCase.contains("path does not exist")||e.getMessage.toLowerCase.contains("table or view not found")=>{logger.warn(s"Tgt $tgtId not found ${jobConfig.job_name}. Init load.");val sF=Seq(StructField(scdC.skIdCol,LongType,false),StructField(scdC.validFromCol,TimestampType,false),StructField(scdC.validToCol,TimestampType,false),StructField(scdC.versionCol,IntegerType,false),StructField(scdC.isCurrentCol,BooleanType,false),StructField(scdC.changeTypeCol,StringType,true));val eS=StructType(tfmDF.schema.fields++sF);spark.createDataFrame(spark.sparkContext.emptyRDD[org.apache.spark.sql.Row],eS)}case e:Exception=>throw new RuntimeException(s"Err read tgt ${jobConfig.job_name}:$tgtId:${e.getMessage}",e)}\n    if(jobConfig.audit_level.toUpperCase!="NONE")try tCurCnt=Some(tgtCurDF.count())catch{case e:Exception=>logger.warn(s"No cnt tgt_cur ${jobConfig.job_name}:${e.getMessage}",e)}\n    logger.info(s"Cur tgt read ${jobConfig.job_name}. Active:${tCurCnt.getOrElse("N/A")}")\n    val nkCols=jobConfig.scd2_natural_keys.getOrElse(throw new IllegalArgumentException(s"scd2_nk req ${jobConfig.job_name}")).split(',').map(_.trim).filter(_.nonEmpty);if(nkCols.isEmpty)throw new IllegalArgumentException(s"scd2_nk empty ${jobConfig.job_name}")\n    val srcBusHC=tfmDF.columns.filterNot(nkCols.contains).toSeq\n    val hDel=jobConfig.job_properties.flatMap(JSON.parseFull(_).collect{case m:Map[String,String]=>m.get("scd2_handle_deletes_by_absence")}.flatten.map(_.toBoolean)).getOrElse(false)\n    val catR=Scd2LogicUtil.categorizeAndDetectChanges(tfmDF,tgtCurDF,nkCols,jobConfig.scd2_change_tracking_column,srcBusHC,hDel,spark)\n    val tgtScdMCN=Seq(scdC.skIdCol,scdC.validFromCol,scdC.validToCol,scdC.versionCol,scdC.isCurrentCol,scdC.changeTypeCol).map(_.toLowerCase)\n    val tgtBusC=tgtCurDF.columns.filterNot(tgtScdMCN.contains).toSeq\n    val finOutDF=Scd2LogicUtil.generateScdOutputRecords(catR,tfmDF.columns.toSeq,tgtBusC,nkCols,scdC,pTs,hTs,spark)\n    logger.info(s"Final SCD output gen ${jobConfig.job_name}.");if(logger.isDebugEnabled){logger.debug(s"Schema finalOutDF ${jobConfig.job_name}:");finOutDF.printSchema();logger.debug(s"Sample finalOutDF ${jobConfig.job_name} (masked):");val foShow=jobConfig.log_masking_columns.filter(_.trim.nonEmpty).map(cl=>LoggingUtil.maskDataFrame(finOutDF,cl.split(',').map(_.trim))).getOrElse(finOutDF);foShow.show(5,false)}\n    val wr=finOutDF.write.mode(SaveMode.Append);jobConfig.target_format.foreach(f=>wr.format(f.toLowerCase));jobConfig.target_format_options.foreach(o=>JSON.parseFull(o)match{case Some(m:Map[String,String])=>wr.options(m)case _=>});jobConfig.partitioning_columns.foreach(pc=>{val c=pc.split(',').map(_.trim).filter(_.nonEmpty);if(c.nonEmpty)wr.partitionBy(c:_*)})\n    jobConfig.target_type.toUpperCase match{case "HDFS"|"FILE"=>wr.save(tgtId) case "HIVE_TABLE"=>{logger.info(s"Save Hive $tgtId for ${jobConfig.job_name}");spark.sqlContext.setConf("hive.exec.dynamic.partition","true");spark.sqlContext.setConf("hive.exec.dynamic.partition.mode","nonstrict");wr.insertInto(tgtId)} case o=>throw new UnsupportedOperationException(s"Tgt type '$o' not supported SCD2 wr ${jobConfig.job_name}.")}\n    logger.info(s"SCD recs written ${jobConfig.job_name}.")\n    if(jobConfig.audit_level.toUpperCase!="NONE")try rWriteCnt=Some(finOutDF.count())catch{case e:Exception=>logger.warn(s"No cnt final_out ${jobConfig.job_name}:${e.getMessage}",e)}\n    if(jobConfig.reconciliation_enabled.equalsIgnoreCase("Y")&&jobConfig.reconciliation_config.exists(_.trim.nonEmpty)){logger.info(s"Recon ${jobConfig.job_name}(SCD2 CurVw)..." );try{val sR=tfmDF;val curTgtS=jobConfig.target_type.toUpperCase match{case "HDFS"|"FILE"=>spark.read.format(jobConfig.target_format.getOrElse("parquet")).load(tgtId).filter(col(scdC.isCurrentCol)===true)case "HIVE_TABLE"=>spark.table(tgtId).filter(col(scdC.isCurrentCol)===true)case o=>throw new RuntimeException(s"Cannot get tgt snap SCD2 recon type $o ${jobConfig.job_name}")};val rp=ReconciliationService.executeChecks(jobConfig.job_name,sR,curTgtS,jobConfig.reconciliation_config.get,spark);logger.info(s"ReconRep ${jobConfig.job_name}(SCD2):St-${rp.overallStatus}");rp.checkResults.foreach(c=>logger.info(s" Ck:${c.checkType},St:${c.status},Msg:${c.message}"));if(rp.overallStatus!="PASS")logger.warn(s"Recon ${jobConfig.job_name}(SCD2) st:${rp.overallStatus}.")}catch{case e:Exception=>logger.error(s"Err SCD2 recon ${jobConfig.job_name}:${e.getMessage}",e)}}\n    if(jobConfig.dq_checks_enabled.equalsIgnoreCase("Y")&&jobConfig.dq_rules_config.exists(_.trim.nonEmpty)){logger.info(s"DQ ${jobConfig.job_name} on cur_tgt_vw...");try{val curTgtSnapDQ=jobConfig.target_type.toUpperCase match{case "HDFS"|"FILE"=>spark.read.format(jobConfig.target_format.getOrElse("parquet")).load(tgtId).filter(col(scdC.isCurrentCol)===true)case "HIVE_TABLE"=>spark.table(tgtId).filter(col(scdC.isCurrentCol)===true)case o=>throw new RuntimeException(s"Cannot get tgt snap DQ type $o ${jobConfig.job_name}")};val dqRep=DataQualityService.applyChecks(jobConfig.job_name,curTgtSnapDQ,jobConfig.dq_rules_config.get,spark);dqRepOpt=Some(dqRep);logger.info(s"DQ Rep ${jobConfig.job_name}:St-${dqRep.overallStatus}");dqRep.rule_results.foreach(rr=>logger.info(s" DQ Rule:${rr.rule_name},St:${rr.status},Fail:${rr.failing_records_count.getOrElse("N/A")},Msg:${rr.message}"));if(dqRep.overallStatus=="FAIL"){logger.error(s"Crit DQ fail ${jobConfig.job_name}.Failing job.");throw new RuntimeException(s"Crit DQ fail ${jobConfig.job_name}.")}}catch{case e:RuntimeException if e.getMessage.startsWith("Crit DQ fail")=>throw e case e:Exception=>logger.error(s"Err DQ ${jobConfig.job_name}:${e.getMessage}",e);throw new RuntimeException(s"Err DQ subsystem ${jobConfig.job_name}",e)}}\n    logger.info(s"SCD2 ${jobConfig.job_name} completed. Written/Affected:${rWriteCnt.getOrElse("N/A")}");(tSrcCnt,rWriteCnt,dqRepOpt)}\n}
